INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p275218-ee399', 'stk-user474', 'EE 399', 'info', '{"desc": "قصدك تنافس على حب الخشوم 😆\nيا أخي إذا كان تدريبي الصيفي في أرامكو الظهران, و كنت بقسم به 3 مهندسين من البترول دفعة 89 و كلهم ماجستير, و ما أحد مسك منهم شيء إلا واحد حطوه سوبرفايزر بعد ما طلعت له صلعه كبيره, يعني بالله عليك 14 سنة مهندسين خبرة والله له ثقلهم و في الأخير يجي السوبرتنده و يحط القبيلي مكانهم من جماعة قد يحابيها على المساكين هل الديرة. والله إنهم يشتكون منه و إنه ظالمهم, و هم يجاملونه, هه قال تنافس قال.\n\nرح رح أقول لحق على رئيسك شبكه و اعزمه في البحرين أصرف لك من أحلام اليقظة, و الله واحد من الشباب كلمته اليوم من الفرش من اللي قتلوا مواهبهم و حطوهم في تخصص في وادي آخر لا و يقولي زهقققق, و الحين يقدم على شركات أخرى.\n\nأما تقول الجو فاضي عندنا بلا تنافس فالادارة ما تلعب و ما عندها تقول ذا سعودي و ذا مصري, والله الله إني مريت على دائرتين بها قسمين ماسكها مصري و الثاني هندي يعني استيراد خبرات,\n\nبالعربي أنت كفو بتمسك, بلية اقعد عند البقر احلبها, و الا حب الخشوم ما قال شي. 🤣", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/63544/51", "user": "user474", "ts": 1213699058000, "tid": 63544, "pn": 51}}', 1213699058000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1499346-ee399', 'stk-m_nd_m', 'EE 399', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم و رحمة الله و بركاته\n\nقمت بإنشاء استبيان يلخص تجارب الطلاب في برنامج أرامكو الصيفي، يحتوي على معلومات و نصائح و غيرها.\n\nالنتائج ستقسم لقسم أسئلة عامة و قسم التجارب:\n\n**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(1\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-7-3.png|644x316](upload://5KO3SUeZcF4ldwNQjNE0WTv08Ye.png)**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(2\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-9-14.png|909x413](upload://yZ9wfdQS7Y4QfDEwI3qXcJhY1hQ.png)**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(3\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-9-37.png|875x457](upload://iS8gC07uQWP2CjtkVdLpnqkChh9.png)**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(4\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-9-57.png|889x380](upload://hvB1XYW1vc3btiiMptpbmvU2TCv.png)**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(5\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-10-12.png|877x395](upload://eWd2KvuEn9lXxR5UTjFPDGnCKgw.png)~~~~~~~~~~~~~~~~~~~~~~~~تجارب~~~~~~~~~~~~~~~~~~~~~~~~عدد \\(10\\) مشاركات: 8 ميكانيكال \\- 1 بتروليوم \\- 1 كهرب5 أسئلة كالتالي/\\(e.g. Project Management Team or PMT\\) القسم \\- Department\\(e.g. Forecasting & Logisitics Division or F&LD\\) الشعبة \\- Division\\(e.g. Gas Forecasting Unit\\) الوحدة \\- Unitطبيعة عمل القسم \\- Departments Work | \\(مثال: التأكد من توفر المواد لاستمرار المشاريع و عدم توقفها\\)إضافات \\- Additions | \\(التحدث عن بيئة العمل، أي نصائح، جدية التدريب، المواصلات، السكن، إيجابيات، سلبيات، الدوام، الحضور الخ الخ\\)\\*\\*\\*ملاحظة: لم يتم التعديل على أي من الردود\\*\\*\\***\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(1\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****FrPD****SIS****Support service unit****Protect assets & save lives****You’ve got to be able to work in a team \\+ to communicate with others \\+ leave a good impression** **\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(2\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****Northern Area Pipelines Department****Maintenance Division****Maintenance planning, engineering unit****Transport oil and gas from refineries to factories by operating and maintaining the pipeline network and its facilities in a safe and environmentally friendly manner using modern technologies.****انا كنت تبع ال maintenance ولكن ال mentor قال لي بما إن التدريب مدته ٨ اسابيع وهي تعتبر مدة قليلة وانا ابيك تاخذ فايدة كبيرة****راح اقسم الخطة الى التالي :****2 weeks in Operation Division****2 weeks in Maintenance Division****2 weeks in Hot tap & Stopple Division****2 weeks in Engineering Division****بكل صراحة تجربة التدريب عندهم مو مرتبة ابداً****م عندهم برنامج معين ومحدد لتدريب الطالب واول اسبوع يوم رحنا م كانوا يدرون اصلاً ان في طلاب تدريب صيفي عندهم.****بالنسبة للمواصلات كنت اروح واجي بسيارتي.****م اعطونا سكن .****ايجابيات :****اللي قابلتهم هناك يحرجونك بأخلاقهم العالية ويبون يعلمونك قد م يقدرون لكن بيئة العمل احياناً تمنعهم من هالشي. لان مو كل وقت الموظفين فاضين عندهم اجتماعات و الخ ...** **فكرة تقسيم التدريب الى اسبوعين في كل division كنت فكرة ممتازة واخذت فائدة كبيرة منها.****سلبيات :****م فيه برنامج معين للتدريب وتحس كل شي ملخبط وتجي لك ايام احياناً م تسوي شي اساساً ف يكون مضيعة للوقت مع الاسف.****الدوام من ٧ الى ٤.****لكن كان فيه flexibility بحيث لو خلصت شغلي وماعندي شي اسويه اقدر امشي.****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(3\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****EXPEC ARC****PTT****Advance well complition** **البحث عن حلول جديدة لتحديات يواجهونها في حقول البترول****المكافأة بالضبط كانت 3083.33 الشهر الأول****الشهر الثاني باقي ما وصلت****ايجابيات:****١\\- في تعاون كبير جدا ومرونه مع ظروف الطالب****حصلت معاي حالت وفاة وعطوني الاربعاء والخميس اجازة اذا عندي موعد او اي شيء طارئ يسمحون لي بالخروج وبسهوله** **٢\\- بعض الموظفين متعاون وتحس انه يبغا يفيدك وقد ما تسئلة يجاوب بدون ما يحسسك انه مل منك او تضايق وبعضهم يصرفك وما له خلق** **السلبيات:** **١\\- انا ميكانيكال انجنيير و ٩٠٪؜ من الشغل كان كيمياء مع ان الشغله الي كنت اسويها عاجبتني لكن ما كانت تضيفلي اي شيء كمهندس ميكانيكي والديبارتمت الي كنت فيه بشكل عام ما عندهم شغل حق المهندس الميكانيكي****٢\\- توزيع الطلاب بناء على التخصص ما كان ممتاز ابدا لأن كان ممكن يحطوني في ديبارتمنت ثاني له علاقة اكبر بتخصصي وكان استفدت اكثر****بشكل عام كانت تجربه رائعة واستفدت منها كثير من ناحية اجواء الوظيفة والمهام الوظيفية الي تجي الموظفين والنشاطات الي تسويها الشركة والاجتماعات وكيفية التعامل معاها****لكن زي ما ذكرت فوق للأسف ما حصلت الفايدة الي كنت احتاجها كمهندس ميكانيكي****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(4\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****PMT****Marjan Downstream Pipelines****\\*No Unit Mentioned\\*****Design Office** **I Got engaged with the designers\\(the contractor\\) to know more about pipelines and their designs and also understand how to read the P&ID which is Piping and Instrumentation Diagram. Finally I was assigned in the E\\-Review System which is a system where the reviewers put their comments in the designs so the designers see where the mistakes are and they correct them, my assignment was to approve that the designers had corrected their designs based on the implemented documents and upload them on the system.** **\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(5\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****Inspection Department****ما اذكر بالضبط****Advanced Non Distractive Test Services Unit****عمل الفحوصات على المعدات الميكانيكية والبيبات** **كان العمل جماعي ، وما لاقيت صعوبة ، قرب العمل من الجامعة جعله مريح ...****تجربة قصيرة الوقت ، لكن تغيير جو****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(6\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****Process and control systems department****Energy systems division****Energy systems optimization unit****Energy audit for non\\-industrial building** **بيئة العمل جدا ممتازة \\( تعاون ، اخلاق ، النصائح \\)** **\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(7\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****Maintenance****Reliability****\\*No Unit Mentioned\\*****صيانة الكومبرسرات والبمبات****للامانة لم يركزو علي للقيام باي عمل بتاتا، اغلب الايام جالس عالمكتب وكم يوم كان ياخذني واحد من التكنشنز للمصنع عشان اتفرج ولا شيء اخر، تندمت على التطبيق معهم****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(8\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****ITC****Job skills****Electrical core****لايوجد****.****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(9\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****EXPEC Arc****Production technology**\\*No Unit Mentioned\\*اجراء الأبحاث والعمل على تطوير تقنيات الانتاج وحل مشاكل المتعلقة بالانتاجبيئة العمل كانت جيدة ومريحة.من ناحية جدية التدريب فهو يعتمد على المشرف على الطالب وعلى الطالب أيضا. فالطالب يقدر يطرح أسئلة و يتكلم مع الموظفين حتى لو موب في نفس الفريق او القسم. فالشيء هذا يبين ان الطالب مهتم وممكن ياخذ شغل اكثر وينظرون للطالب بجدية. انا من سكان مدينة الخبر فما كان عندي مشكلة في المواصلات او السكن. من السلبيات ان مرات يكون غير سوء تنظيم بين الجامعة والشركة. قابلت بعض الطلاب خططهم ما كانت جاهزة و عدد كبير تأخر حصولهم على اجهزة كمبيوتر.**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(10\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****\\(تجرتبي الشخصية، اللي عنده أي سؤال يتفضل\\)****PMT**Forecasting & Logisitics DivisionGas Forecasting Unitباختصار التأكد من توفر المواد \\(مثل البايبس و الفالفز\\) لاستمرار مشاريع الغاز و عدم توقفها.الإضافات على شكل نقاط: - تعامل الموظفين كان جميل جدًا و متعاونين لأقصى درجة. - قعدت أسبوع و شوي بس عشان أستلم جهاز و أفعل حسابي و الـPulse، برأيي سوء تنظيم و تخطيط. - مافيه شغل إلا إذا نشبت باستمرار \\(وهذا اللي حاولت أسويه\\) أو إذا تعرف أحد يقربلك ممكن يساعدك، أما إذا قعدت بالمكتب تنتظر يجي الشغل عندك بتموت زهق. - ما كان فيه متابعة على الحضور و الغياب، لكن من نفسي حاولت ألتزم قدر المستطاع و ماسمعت كلمة وينك متأخر ولا شي من هذا القبيل، بالعكس متعاونين جدًا حتى إني مرضت بأول أسبوع و أصر موظف الإتش أر إني أغيب و أرتاح. - تعلمت كثير أشياء لكن نصيحتي هي النشبة النشبة. - بخصوص المواصلات و السكن مالي علم، بخصوص تذاكر السفر فبإمكانك تسافر مجانًا لكن بتقعد على أعصابك لأنه ما يأكدونلك الحجز إلا بآخر لحظة. أيضًا أرسلوا إيميل تقدم فيه طلب تعويض سكن/سفر. - أرامكو السنة هذه أخذوا عدد كبير جدًا من الطلاب، قبولنا \\(السمر\\) جاء قبل الفاينلات بشوي، مع العلم أنه كان في رسائل قبول قبلها لكن الرسمية الرسمية كانت قبل الفاينلات. - المكافأة نزلت مرتين، المرة الأولى 3080 ريال و الثانية تقريبًا 1400 ريال. - نصيحة حاولوا تاخذون كل الملفات اللي تحتاجونها لكتابة الريبورت قبل ما تخلصون، و اللي يكتب الريبورت و هو هناك أفضل و أفضل. - هذا اللي عندي و إن شاء الله ما نسيت شي، اللي عنده أي استفسار يتفضل حاضرين 😆أتمنى الموضوع يكون مفيد للدفعات القادمة و شكر خاص للشباب اللي شاركوا بالاستبيان، في ميزان حسناتكم إن شاء الله![upload_2018-9-12_1-7-18.png|696x321](upload://tvtYZymrwuQrTPNhWDrmwvkBWV8.png)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/180148/1", "user": "M_nd_m", "ts": 1536768136000, "tid": 180148, "pn": 1}}', 1536768136000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1011708-ee399', 'stk-mohammed10', 'EE 399', 'info', '{"desc": "جبت لكم بعض الشركات اللي توفر تدريب صيفي لطلاب الكهرب.\n\n1- شركة مجموعة الجريسي.\n\n2- مصنع المدرعات والمعدات الثقيلة. (أعتقد إنها حكومية “الحربية بالتحديد”)\n\n3- وزارة الداخلية. 😉\n\n4- شركة يوكوجاو. 👀\n\n5- شركة فارابي الخليج للبتروكيماويات.\n\n6- الكهرباء 😞. 😂 سكيكو\n\n7- سيمنس. 👍 وأعتقد إن بتوع الالكترونيكس راح يستفيدون هناك\n\n8- هيئة الاتصالات وتقنية المعلومات. واضحة \"الكوميونيكيشن ❤️ \"\n\nعاد البركة فيكم شباب >>> ورونا شطارتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/123159/4", "user": "mohammed10", "ts": 1332096716000, "tid": 123159, "pn": 4}}', 1332096716000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1069687-ee399', 'stk-user5643', 'EE 399', 'info', '{"desc": "- التسجيل ( الموعد , الطريقة)\nزي ما تسجل اي كورس ثاني … في كورس اسمه summer training نزله\n- مدة التدريب الصيفي\n8 weeks\n- المطلوب من المتدرب اثناء فترة التدريب\nيختلف من شركه لشركه … الجامعه تطلب منك ترسل خطة التدريب ( تطلبها ن الشركه ) و ريبورت\n- إجراءات ما بعد التسجيل\nدور لك شركه اما عن طريق الجامعه او انت دور\n- فوائد التدريب الصيفي في المستقبل الوظيفي\nيعطيك فكره عن بيئة العمل\n- أفضل الشركات للتدريب\nما اقدر افيدك اعذرني\nبالنسبة للشركات ابغى استفسر عن الشركات الي بالشمال (عرعر والجوف) للتدريب الصيفي ؟\nاعرف واحد بشركة الكهرب بالجوف مدري سكاكا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/129058/2", "user": "user5643", "ts": 1342777728000, "tid": 129058, "pn": 2}}', 1342777728000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1006863-ee399', 'stk-user6008', 'EE 399', 'info', '{"desc": "*وش تطمح في التدريب يعني وش تتوقع من الشركة اللي تدربك ؟\nما عندي خلفية عن الموضوع، لكن بشكل عام أتمنى أن يكون في البداية شرح مفصل لسير العمل ثم تسند لي مهام في مجال تخصصي (تساعدني على فهم التخصص)\n*وش افضل الشركات اللي ودك تتدرب فيها… ؟\nأرامكوا - سابك - شركة الكهرباء - ولو حصل شركة إتصالات ما نقول لا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/122715/4", "user": "user6008", "ts": 1331637727000, "tid": 122715, "pn": 4}}', 1331637727000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1404830-ee399', 'stk-user3498', 'EE 399', 'info', '{"desc": "السلام عليكم\n\nتلقيت طلب من احد الاعضاء بأن اقوم بعرض تجربتي في الدراسة والوظيفة بعد التخرج كمهندس مدني , ولتعم الفائدة سأقوم بتقديم نصائح لكافة المراحل في التخصصات الهندسية , وبالنسبة للهندسة المدنية سأقوم بكتابة موضوع منفصل عن تجربتي الشخصية\nسأقوم بترتيب المقال على شكل نقاط مختصره لاختصار الوقت وتبسيط الفكرة\n\n, دعواتكم لي بالشفاء اعاني من مشكلة في الظهر\n\nأولا : الاوريا :\n\n- قد تكون اصعب مرحلة في الجامعة لعدة عوامل منها :\n\n1- التغير المفاجئ في نمط الحياة ( ساعات الدوام الطويلة )\n\n2- المناهج الجديدة ونمط الاختبارات والكويزات والهوموورك المختلف كليا عن الدراسة العادية\n\n- سوف تقوم بدراسة مواد متعدده غالبا لتحديد ميولك الابتدائي , مثلا اذا احببت الفيزياء : ميكانيكال , كيميا : كيميكال , رياضيات : الكتريكال وهكذا .\n\n- بعد السنة التحضيرية ستقوم بتحديد تخصصك الابتدائي\n\n- يجب عليك ان تبذل اقصى جهدك لان هذه اهم سنه ووجودك في الجامعة معتمد على هذه السنة ( لا تعتبر طالب في البترول الا بعد اجتيازها بنجاح ) , ابذل اقصى جهد واعتبر ان هذه السنة هي اهم سنة في حياتك كلها ، لان مستقبلك ( نوعيته وجودته ككل ) يعتمد على هذه السنة\n\nثانيا : التخصص :\n\n- اختيار تخصصك الابتدائي لا يعني شيئا في اول سنه ( فريشمان ) لأنك ستقوم بدراسة جميع المواد المشتركة مع باقي التخصصات الهندسية\n\n- بعد السنه الاولى ستقوم بدراسة بعض المواد التي ستعطيك فكره عن التخصصات , مثلا EE 204 ستعطيك فكره عن اليكتريكال , CE 201 ستعطيك فكره عن المدنية وهكذا\n\n- تحديد تخصصك المستقبلي يعتمد على السداسية التالية :\n\n1- ميولك الابتدائي من قبل الدراسة الجامعية\n\n2- ميولك بعد دراسة مادة من التخصص نفسه\n\n3- النتائج ( نتائج الاختبارات ، الكويزات ، الهوموورك ) : ارتفاع نتائجك في هذا المقياس يدل على ان التخصص هذا هو الانسب وذلك وفق معادلة : % الجهد + % الوقت ≈ 70-80% النتيجة\n\nمثال : لنفرض في مادة CE 201 وبعد استلام نتيجتك في الاختبار الاول : انت تعتقد انك بذت جهد كامل 100 % في التحضير للاختبار ( حل جميع الهوموورك + الكويزات + مذاكرة المقرر كامل ) ولم تقصر ابدا في بذل الوقت 100% فاذا كانت نتيجتك في الاختبار تساوي 70-80% او اعلى فذلك يعني ان التخصص الذي تتبعه المادة مناسب في الارجح لك ( هنا CE ) , اما اذا كانت نتيجتك دون ذلك فان التخصص لا يناسبك ابدا .\n\n4- حاجة سوق العمل :\n\nوهي ليست فقط عدد الوظائف , لتفهم حاجة سوق العمل يجب الانتباه للآتي : ( نسبة العرض الى الطلب + مستواك الاكاديمي مقارنة الى مستوى الطلاب في نفس التخصص )\n\nبمعنى : اذا فرضنا انك تفكر في دخول قسم الهندسة الكيميائية ، فعليك اولا ان تقيس حجم خريجي القسم في الفصل الواحد كمعدل ، مثلا 1000 طالب للفصلين الاول والثاني , وهذا العرض , اما الطلب فهو عدد الوظائف المتاحة في سوق العمل فمثلا بزيارة موقع يوم المهنة ، يمكنك معرفة عدد الوظائف المتاحة في ذلك الفصل مثلا 250 وظيفة ( بغض النظر حقيقية او لا ) .\n\nثم تقوم بقسمة العرض على الطلب لتكون عندك نسبة = 250/1000 = 0.25 بمعني ربع وضيفة لكل طالب وهذا سيء جدا ، كلما ارتفعت النتيجة عن 1 كلما كان افضل\n\nثم بعد اخذ فكرة عن العرض والطلب يجب عليك مقارنة هذا الامر مع مستواك الاكاديمي ، فمثلا اذا كنت تعتقد ان مستواك الاكاديمي يوازي C مقارنة بباقي الطلاب في التخصص , فذلك يعني ان نسبة العرض الى الطلب يجب ان تكون مرتفعة ( 2 او اعلى ) لان المنافسة ستكون شديده وستخسر موقعك في التقديم للشركات عند مقارنة المعدل\n\nاما اذا كنت تعتقد انك A ففي هذه الحالة لا يجب عليك القلق ان كانت نسبة العرض الى الطلب اقل من 2 او اقل من 1 ايضا .\n\n5- طبيعة العمل المستقبلي :\n\nيجب عليك الانتباه ان دخولك تخصص معين لا يعني بالضرورة ان ما ستقوم به في عملك هو تطبيق لتخصصك بالكامل ، بمعنى ان الدراسة شيء والعمل شيء اخر .\nيجب عليك قبل الاكمال في تخصصك ان تأخذ فكره واضحة عن الاتي : مجالات وطبيعة العمل في تخصصك ( مصانع –رقوق – مكتبي – الخ) + موقع العمل( موقع يوم المهنة ) + ساعات العمل ( 40 او اكثر في الاسبوع : بمعنى كم ساعة يوميا وكم يوم في الاسبوع ) + معدل الرواتب ( موقع يوم المهنة )\n\nوبعد اخذ فكرة يجب عليك ان تقوم بمقارنة هذا الامر بميولاتك الشخصية . وغالبا افضل طريقة لمعرفة هذا الشيء التدريب الصيفي او التعاوني ، ولكن التدريب غالبا يكون متأخر وغالبا الشركات غير جادة في تدريب الموظف , لذلك الافضل هو البحث الذاتي\n\n6- نظرتك الذاتية لمستقبلك :\n\nيجب ان تحدد هدف وظيفي واضح ، حتى لو لم يكن واقعي ،، فكما يقول المثل : صوب للقمر فان لم تصيب القمر ،، ستصيب النجوم\n\nمثال : انت ترى نفسك بعد خمس سنوات متزوج ولديك ابناء ،، اما وظيفيا فترى نفسك على المدى البعيد : موظف بمرتبة عالية ، مستقر وظيفيا ، مقتدر ماليا ؟ نوعية المرتبة وطبيعة عملها تختلف على حسب مجال العمل والتخصص وذلك تبعا لبحثك الذاتي … ففي هذه الحالة قارن اهدافك بتخصصك ومجالاته الوظيفية\n\nمثال2 : انت ترى نفسك تدير عمل حر بدون ساعات عمل محددة ولا رؤساء ،، تخصصك هو هندسه كيميائية ؟ غالبا في هذا التخصص مجال العمل الحر اصعب وأطول من المدنية مثلا . ( ابحث )\n\nمثال 3 : انت ترى نفسك معيد او باحث في الجامعة ؟ ابدأ بتكوين علاقات وتحسين نتائجك والبحث عن طريقة اكمالك ومتطلباتها .\n\nالخلاصة : بعد تحديد نتائجك في هذا السداسية ، ستقوم بتحديد التخصص المناسب لك او مدى ملائمة تخصصك الحالي\n\nفي الحلقة التالية سأقوم بعرض مرحلة ما بعد التخصص وبعض النصائح المفيدة .\nلأي طلب : s200678180@gmail.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/166127/1", "user": "user3498", "ts": 1413181464000, "tid": 166127, "pn": 1}}', 1413181464000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1488396-ee399', 'stk-mosab_j', 'EE 399', 'info', '{"desc": "الشهادة معتمدة من معهد الجبيل التقني\n\nوهذي معلومات عن البرنامج\n\nرنامج الصيفي للمهارات الفنية الهندسية والتقنية للمهندسين و طلاب الجامعات السعودية\n\nتعريف البرنامج : هو برنامج محاكاة العمل الفني والهندسي لابرز المنشآت الصناعية و شركات توليد الطاقة وهو معتبر بمادة التدريب الصيفي بالجامعات السعودية وغيرها\n\nالهدف من البرنامج : برنامج تدريبي يركز على تنمية أبرز المهارات الفنية والتقنية للمهندسين والتي تطلبها طبيعة العمل في القطاع الصناعي\n\nالفئة المستهدفة : طلاب و المهندسين تخصصات الهندسة الميكانيكية والكهربائية و الصناعية و الهندسة الكيمائية - طلاب الكليات التقنية\n\nطريقة التدريب : التدريب بطريقة ادارة المشاريع عدد ساعات التدريب : 270 ساعة تدريبية يشملها شهادة معتمدة\n\n: مميزات البرنامج\n\nمحاكاة العمل الهندسي لابرز المنشآت الصناعية ومحطات توليد الطاقة الموجودة بالجبيل الصناعية #\n\n# ترسيخ المهارات الهندسية الفنية للمهندسين باعداد مشاريع تخرج خلال فترة التدريب\n\n# التدريب وفق معايير دولية خاصة بمصانع و محطات توليد الطاقة للمدن الصناعية\n\nشهادات معتمدة من معهد الجبيل التقني بالهيئة الملكية #\n\nزيارات لابرز الشركات و المنشآت الصناعية بمدينة الجبيل الصناعية #\n\nسكن لكل المتدربين خلال فترة التدريب #\n\nيعتمد البرنامج التدريبي على اللغة الانجليزية للمفردات التقنية والهندسية #\n\nمعرض للمشاريع المنفذة خلال فترة البرنامج ودعوة ابرز الشركات والمنشآت الصناعية بالجبيل الصناعية #\n\nبرامج ترفيهية وثقافية وواجهة بحرية خلابة #\n\nمدة البرنامج : شهرين لمدة 7 اسابيع تدريبية\n\nبداية البرنامج يوم الاثنين تاريخ 10/10/1439 الموافق 24/6/", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/178856/5", "user": "Mosab_j", "ts": 1519409403000, "tid": 178856, "pn": 5}}', 1519409403000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1448380-ee399', 'stk-user10042', 'EE 399', 'info', '{"desc": "يعطيكم العافية يا شباب\n\nذحين مافي مجال الواحد يتشرط , صعب تلاقي فرصة\nعلى حسب كلام القصاص ارامكو قبلت بس 15 طالب من الهندسة الكهربائة للصيفي\nأول ما كان مسموح انك تأخذ فرصة تدريب بدون راتب , ذحين صار مسموح\nالفرصة هي في شركة الكهرباء ( بدون راتب+ وقت التدريب في رمضان ) بس ايش اسوي\nاذا ما أخذت تدريب حأتأخر سمستر\n\nكلمت القصاص قال كلم الدكتور طلال الخروبي\nأحد يعرف رقم مكتبه ؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/173213/4", "user": "user10042", "ts": 1462732697000, "tid": 173213, "pn": 4}}', 1462732697000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1531233-ee399', 'stk-user11500', 'EE 399', 'info', '{"desc": "يروح وهو مغمض ولا يقلق عن شيئ أبدا\nشركة سكيم قوية جدا\nصاحبي تدرب عندهم لمدة شهرين تدريب صيفي للدبلوم وبعدين اشتغل فيها سنتين وكان يوصل راتبه 15000 ريال لكنه طلع منها وراح يدرس بكلريوس في أمريكا هندسة كهربائية\nوحاليا يقول لو أنا باقي فيها أفضل من دراستي الهندسة\nسكيم شركة قوية جدا جدا\nالمهندس الفرش بعد سنتين يعطونه 200000 ريال لتحسين الأوضاع وإجازات سكيم حلوة\nالله يوفقه لكل خير\n\nسؤال أخي :\n\nكيف قدم عليهم وما هو تخصصه؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-chem-chevron/184117/3", "user": "user11500", "ts": 1628941840000, "tid": 184117, "pn": 3}}', 1628941840000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1069655-ee399', 'stk-user5216', 'EE 399', 'info', '{"desc": "- التسجيل ( الموعد , الطريقة)\n\nتسجل التدريب الصيفي me399 في الترم الصيفي عن طريق النت ( مثل طريقة تسجيل المواد بالضبط )\n\n- مدة التدريب الصيفي\n\n8 اسابيع\n\n- المطلوب من المتدرب اثناء فترة التدريب\n\nمحاولة تطبيق لما تعلمته على ارض الواقع\nومطلوب منك بنهاية التدريب ريبورت من 20 الي 40 ورقه\n\n- إجراءات ما بعد التسجيل\n\nماادري ليه شاغل نفسك من الحين باقي عليها سنه … لكن بعد تسجيل السمر راح يطلب منك تعبي ورقة ابروفل وتوقعها منالادفايزر حقك وكوردينيتر التدريب الصيفي + ختم القسم\nفائدة هالاجراء هو التاكد من اتمامك لمتطلبات السمرترينيق\n\n- فوائد التدريب الصيفي في المستقبل الوظيفي\n\nيعطيك خبره حلوه + ممكن يحدد ميولك الوظيفيه ( بعض الطلاب مثلا يقرر يكمل دراسته بعد ماشاف وضع الشركات والعكس صحيح )\n\n- أفضل الشركات للتدريب\n\nانا اشوف الشركات الاجنبيه لانها تكرفك مما راح يخليك تستفيد اكثر ( اذا تبي الفايدة )\nاما اذا ودك بالراحه ( عندك ارامكو وسابك وشركة الكهرباء … )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/129057/2", "user": "user5216", "ts": 1342758184000, "tid": 129057, "pn": 2}}', 1342758184000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1008256-ee399', 'stk-user6200', 'EE 399', 'info', '{"desc": "بعطيك التفاصيل اللي صارت معي يمكن تفيدك\n\nانا طبقت عند اهلي بشركة الكهرباء\n\n1- اول شي كلمت مسؤول التدريب بشركة الكهرباء بجدة واعطاني رقم الفاكس حقهم\n\n2-عبيت الفورملا بالمعلومات الرئيسية وتكتب خطاب بالعربي (ورود طبعا) لمسؤول التوظيف اني طالب على وشك التخرج واود التدريب في مدينة كذا حيث اني من سكان هذي المحافظة وووووو واتمنى منكم الموافقة على ذالك وطبعا (كتبت رقم بالاخير فاكس ادارة التدريب)\n\n3- اتصلت عليه قبلها اني برسلها هاللحظة الاوراق قال ارسل وارسلتها عليهم فاكس من الجامعة (خطابي و ورقة فرصة تدريب و صورة بطاقة الاحوال)\n\n4- رجعوها لي بعدها بفترة رحت استلمت الموافقة من مكتب ادارة التدريب وكان مكتوب مكان العمل جدة كان على بالي حاطيني بجدة ومعها ظرف من الجامعة\n\nالمهم قبل التدريب باسبوع رحت لهم جدة عشان اخذ اوراقي والموافقة على تدريبي منهم لجهة التدريب الفرع يعني\n\nوصلت قالي انت تبي المحافظة الفلانية التابعة لنا قلت نعم وقالوا خلاص توجه هناك وتدرب هناك موفق واعطوني اوراقي\n\nوتوكلت على الله\n\nالزبدة اذا انت تبي ابها او فرع بابها او مدينة بالجنوب\n\nلازم ترسل للادارة القطاع مو للفرع او مكتب الكهرباء لانه مو من صلاحياتهم\n\nزي انا كنت ابي محافظة قريبة من المدينة المنورة ارسلت لجدة لانها ادارة قطاع المنطقة الغربية كلها وهي توزعك\n\nوانت اعلم مني بديرتك شوف وين اداراة قطاعكم وخذ فاكس المسؤول او روح اي فرع وكلمهم يعطونك رقم مسؤول في القطاع حقهم وكلمهم بالتليفون لين توصل للمسؤول التدريب بالقطاع حقكم\n\nهذا اللي عندي\n\nموووووووفق خييييييير اتمنى اكون افدتك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training/122974/4", "user": "user6200", "ts": 1331758110000, "tid": 122974, "pn": 4}}', 1331758110000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1011727-ee399', 'stk-user2728', 'EE 399', 'info', '{"desc": "إعلان ارامكو (وباقي إعلانات التدريب الصيفي) يوصل عادة للي مستواهم جونير وسينير\nفما هي مقصودة أبدا لك أنت شخصيا\n\nإذا أنت بتتخرج في 131\nفيه صيف آخر 123 يمديك أيضا تأخذ فيه سمر تريننق وهو الأفضل\nلأنك تقريبا أنهيت كافة الكورسات إللي راح تفيدك في التطبيق وبتساعدك تفهم التطبيق بخلفية علمية ممتازة\n\nإذا أنت مخلص متطلبات التريننق وناوي الصيف تنزل 113\nأول شيء: التسجيل بأرامكو إنتهى وما لك إلا الواسطة أو تروح لهم مركز التوظيف تطلب منهم يسجلونك هناك\n\nثاني شيء: التسجيل بالشركات الثانية:\nإنتظر تقريبا لمدة شهر بتلقى إدارة التدريب موضحة لكم كل التفاصيل وعارضة لكم الشركات إللي بتطبقون فيها\n\nونصيحتي يفضل أنت تجيب الموافقة من الشركة ولا تعتمد على الجامعة، لأن تخصصات الكهرباء والميكانيكا والكيميكال فيه عروض قليلة لهم مقارنة بالطلاب إللي رايحين يطبقون خلال آخر سنتين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/123220/2", "user": "user2728", "ts": 1332098138000, "tid": 123220, "pn": 2}}', 1332098138000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1443818-ee399', 'stk-abu_khaled', 'EE 399', 'info', '{"desc": "المقابلة الاولى تكون مع شؤون الموظفين, تعرف بنفسك, وش تعرف عن الشركة وليش اخترتها, نقاط قوة ونقاط ضعف ومن الاسئلة هذي\nاهم شيء لا ترتبك وحاول تكون طبيعي جهز نفسك زين وجهز الـ cv , البس لبس محترم\n\nاذا عديت هذي المقابلة ان شاء الله , فيه اختبار تحريري, رياضيات , انجليزي , فيزياء (ميكانيكية و كهربائية)\n\nبعدين المقابلة الثانية, بيقولون لك تجهز برزنتيشن بتتكلم فيه عن نفسك, مشروع التخرج, التدريب الصيفي او الكو اب , وش تعرف عن الشركة و ليش اخترتها (اذا وصلت للمقابلة الثانية بيرسلون لك ايميل موضح فيه الي يبونه منك في البرزنتيشن و كم الوقت الي عندك) يوم مقابلتي قالو لنا كل واحد له 15 دقيقه, القينا البرزنتيشن قدام 5 من المدراء + مدير التوظيف و طبعا بعد البرزنتيشن بيسؤلونك, عاد الاسئلة هذي صعب تحددها, مثل واحد سألوه تعرف كم قيمة برميل النفط اليوم؟ !!!\n\nاذكر ذاك اليوم اكثر من واحد جاله نفس السؤال: عندك مشكلة لو تشتغل في جنوب افريقيا؟\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/172407/7", "user": "abu_khaled", "ts": 1457290576000, "tid": 172407, "pn": 7}}', 1457290576000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1512774-ee399', 'stk-mhran515', 'EE 399', 'info', '{"desc": "انا اخوك من جامعة ام القرى تخصص هندسة ميكانيكية معدلي 3.50 من 4 … تخرجت بتاريخ 1440/5/9 هـ\nالتدريب الصيفي عندنا في ام القرى تدريبين كل واحد مدته شهرين\nالاول كان في مصنع كسوة الكعبة المشرفة في مكة\nالثاني كان في شركة الكهرباء محطة التوليد في مكة\n\nوالله ما لقيت اي وظيفة وانا اقلك يا غالي اذا تسوي في خير وتلقى اي شي لي حتى لو بمنطقة خارج الغربية ماعندي اي مشكلة اروح والله لاني والله بحثت واجتهدت في البحث عن وظيفة “مهندس ميكانيكي” وما لقيت…\n\nبالنسبة لكلامك عن ارامكو فعلا انت صادق ارامكو حلم كل واحد يتمناه لكن يوم تقارنهم مع المعلمين غلط لان احنا المهندسين قليل جداً الي يلقى فرصة بارامكو او شركة مثل مميزاتها اما المعلمين حتى الهامل ابو معدل 1.5 يصبر كم سنة وينزل تعيينه\n\nوزي ما قلت انت انا شفت الوضع وفكرت مالقيت بهالوقت شي افضل من العسكرية وقلت لاصحابي اللي مايبونها وما قدموا عليها قلت لهم بالحرف الواحد انا احترم رايكم لكن اقعدو صدقوني محد يوظفكم والسنة الجاية بشوفكم جايين تقدمون على العسكرية لكن ان شاءالله فال الله ولا فالي\n\nوالجندي يا اخوي يستلم مع البدلات 7 الاف ونص وهو بعد الثانوية اخذ دورة مدتها 4 شهور وفيه قطاعات زي الحرس الملكي الجندي اللي داخل بالثانوي يستلم 8 الاف ونص غير الشرهات اللي تجيه بين فترة وفترة\n\nلكن العسكرية ماهي مثل ارامكو … ارامكو او الشركات بشكل عام كل شي تسويه بحق مافيه شي تسويه بلاش صح انها كرف لكن كل شي له بدل اوفر تايم الخ … ما يضيعون تعبك\nاما العسكرية ترابط وتستلم وتجلس وقت واحيانا تنحرم من الاعياد واجازات السنة اللي كل الناس يوجزون فيها ومالك لا بدل ولا اوفر تايم ولا شي انما يعتبر هذا من واجبك\n\nعموما الدنيا حظوظ والله انا افكر الان اقول ليتني دخلت اي حاجة ثانية… رياضيات او لغة عربية او شريعة\nكان مديني لقيت اشياء كثيرة\nحتى لو كنت افكر بالعسكرية ما كان تعبت نفسي بالهندسة كان اخذت لغة عربية ودخلتها\nلكن الله المستعان والله شي يحزن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181748/26", "user": "mhran515", "ts": 1563789937000, "tid": 181748, "pn": 26}}', 1563789937000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p691683-ee399', 'stk-the_maestro', 'EE 399', 'info', '{"desc": "اخي كوكتيل ،،\n\nبالنسبة لي شخصيا كنت من البداية حاب اني ادرس هندسة ،، و كان الاقرب لي تخصص الهندسة الكهربائية ،،، طبعا انا ما دخلت هندسة كهربائية لاني مولع بها من الصغر او شي من هالقبيل ،،، انا كان توجهي اني ادرس هندسة لاحصل على دماغ تعرض لتجربة دراسية قيمة من الطراز الاول ،، و دراسة الهندسة واحدة من افضل المضامير لخوض مثل هالتجربة ،،، دراسة الهندسة تفتح لك افاق واسعة ،، لما تجي تشوف كيف نظرتك كدارس هندسة و كيف تقبل دماغك للعلوم الاخرى اللي ما درستها من قبل ،،، بتحس بفرق كبير بينك و بين غيرك من دارسين لتخصصات هي اقل مهاراة و اقل تكتيك من دراسة الهندسة ،،،\n\nالامر الثاني توجهي لماجستير ادارة الاعمال بدلا من دراسة تخصصي ،، انا مثلا ما ذكرت سابقا ،، انا اصلا درست الهندسة الكهربائية و لكن لم امارسها يوما ما -عدا التدريب الصيفي- غير ذلك لم امارسها عمليا قط من تخرجي من الجامعة 2005 الى الان ،،، و انا لا اعتبر نفسي مهندس كهرباء ،، بل حامل شهادة و فكر هندسي ،، فضلا عن اني لا ارغب في التخصص الاكاديمي - اقصد ماجستير في الهندسة الكهربائية - و لكن احب ان اطور مهارات اخرى في شخصيتي و من اهمها هي الجانب الاداري بعد ان اسست الاسس المعقولة للجانب العملي …\n\nفعلى هذا الاساس قررت دراسة ماجستير ادارة الاعمال ،،،\n\nتحياتي\n\nاخوك المايسترو", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/schlumberger/89769/91", "user": "The_Maestro", "ts": 1282907392000, "tid": 89769, "pn": 91}}', 1282907392000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p105695-ee399', 'stk-user1806', 'EE 399', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nانا عندي تدريب صيفي في ارامكو الظهران\n\nانا تخصصي كهربائية\n\nوحاب افتح صفحة لتبادل الافكار والمواد التعليمية والمستفادة من هذا التدريب …\n\nانتظر تفاعل الاخوان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/51325/1", "user": "user1806", "ts": 1153202642000, "tid": 51325, "pn": 1}}', 1153202642000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1005223-ee399', 'stk-meemo911', 'EE 399', 'info', '{"desc": "بسم الله الرحمن الرحيم\nالسلام عليكم ورحمة الله وبركاته\nهذي اول مشاركة لي في هذا الصرح الجميل\n\nموضوع باختصار… أول شيء راح اعرف عن نفسي\nأنا طالب هندسة كهربائية جامعة الطائف على وجه تخرج ان شاء الله هذا الترم ومعدلي 3.17 من 4 وعمري 22 سنة ونص 🤠\nحاصل على شهادة ielts بدرجة 6.5 قبل شهرين … وجاهز لبدء الدراسة بدون سنة لغة … وكمان حاصل على شهادة تدريب صيفي لمدة شهرين في شركة ارامكو الصيف الماضي …\nقولوا ماشاء الله 🥰 \" والله عارف انه في ناس احسن مني 👍 \"\nالموضوع باختصار … أنا الصراحة اتمنى اني التحق ببرنامج الابتعاث المرحلة الثامنة والدولة هي بريطانيا ولا غير بريطانيا … لكن محتاااار وبشدة … فاللي أبغاه منكم لو أنت مكاني وتخرجت بالهشهادة … فايش راح تفضل … وظيفة في شركة كبيرة ( ارامكو – سابك – الكهرباء - … ) وبراتب مجزي ( حوالي 11 ألف ريال توتال في الشهر ) أو الابتعاث وتحقيق حلم الابتعاث لكن ماراح تكون ضامن بعد الله فرصة العمل بعد الانتهاء من الماستر …\nالشيء الثاني … إذا ربي يسر وانكتبت لي البعثة … هل انت مع الرأي اللي يقول خذ الماستر والدكتوراه والا اكتفي بالماستر وارجع ابحث عن فرصة عمل سواء اكاديمي محاضر أو شركة كبيرة… أنتظر اجاباتكم لأنها بعد الله راح تحدد كثير من ملامح مستقبلي … ولكم الشكر ❤️ 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/122766/1", "user": "meemo911", "ts": 1331476921000, "tid": 122766, "pn": 1}}', 1331476921000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1456877-ee399', 'stk-user8581', 'EE 399', 'info', '{"desc": "2 - إجرائات الجامعة / الشركة .\nطريقة التقديم : في نهاية الأسبوع العاشر من السمستر الثاني القسم يرسل للطلاب المرشحين للتدريب رسالة عن فرص تدريب بشركة JGC فيها شروط القبول في التدريب الخارجي بالإضافة لشروط الشركة .\nالشروط غالبا :\n- سعودي الجنسية ( شرط الشركة )\n- معدل 3 ( وأحيانا 2.75 )\n- ما سبق للطالب إنه طلع في برنامج التبادل الطلابي أو زيارات دولية\n- افرج قريداته في الانجلش C+\n\nوهذه هي رسالة من قسم الهندسة المدنية :\n\n[/quote]\n\n[quote]\n\nTo Summer Training Students in Term 153 :\nI want to inform you that as part of the cooperation between JGC Company (Japan) and Saudi Arabia , there is ONE opportunity for a civil Engineering student to train in Japan. The requirement to be a candidate include : CGPA & MGPA 2.75 or above , average English courses grade C+ or better, and to be a Saudi national\nIf you plan to register for CE 399 in term 153 , and are interested and satisfy the minimum requirements please contact Dr Khathlan (16-138) as soon as possible and bring with you the following;\nCGPA =\nMGPA=\nGrades in ENGL 101 , 102 & 214 =\n\nبعد اسبوع القسم يرفع أسماء الطلاب المرشحين لإدارة التدريب و عمادة شؤون الطلاب . وبعدها راح يطلب منكم سكرتير إدارة التدريب نسخة من الـ cv والجواز والأحوال عشان يرسلها للشركة … بعد أسبوعين راح تتواصل معكم الشركة ويسون معاكم مقابلة في مقر الشركة بالخبر . ( مكان الشركة )\n\nالمقابلة : تكون على حسب تخصصك وعدد الطلاب المرشحين معك : تقريبا المرشحين كانوا 6 طلاب\n3 طلاب من الهندسة المدنية : سو لهم إختبار يتكون من 3 أقسام لها علاقة بالأساسيات في CE201/CE203/ وعن structural steel لو جبت درجة سيئة في قسم structural steel علم الموظف إنك ماخذت الكورس . بعد الإختبار فيه مقابلة بسيطة والاسئلة فيها كلها شخصية مثلا قد سافرت لليابان أو برا السعودية ؟ , أهلك راضين إنك تدرب برا ؟ وش تعرف عن اليابان ؟ والهدف منها يعرف إنك مستعد وعادي عنك تطلع تدريب برا أو لا . ( طالب بس الي انقبل من الـ 3 )\n\nطالب من الهندسة الميكانيكة : المقابلة كانت شخصية وما سو له إختبار . ( مقبول )\nطالب من الهندسة الكهربائية : المقابلة كانت شخصية وماسو له اختبار . (مقبول )\nطالب من هندسة نظم التحكم والقياس ( انا 🤠 ) : المقابلة كانت شخصية وعن بعض أساسيات التخصص بدون اختبار . ( مقبول)\n\nنصيحتي في المقابلة حاول تبين له إنه عندك فكرة عن برنامج التدريب عندهم و أقسام الشركة وأنك مرن من ناحية التدريب برا السعودية وعندك فكرة عن الحياة في اليابان . اطلع على هذا الملف فيه نبذة عن الشركة وبرامج التدريب (link )\nنتائج المقابلة تعتمد على موعد المقابلة أنا علمني إني مقبول بعد المقابلة على طول أما الشباب الي من الهندسة المدنية بعد أسبوعين ردوا عليهم .\n\nبعد النتائج راح تبدأ اجرائات الشركة وفي نفس الوقت اجرائات الجامعة لكن عشان تكون الصورة واضحة راح اذكر اجرائات الشركة اول شي :\n\nاجرائات الشركة : ( الشركة متعاونة جداً والاجرائات سهلة جداً لكن السلبية الوحيدة هي لأن الاجرائات كانت على نهاية 152 فيمكن تضطر تراجعهم في الاجازة بين 152 و153 . )\n\n- بعد القبول بفترة راح يجتمع معكم موظف HR عشان يعطيكم فكرة عن البرنامج ويعطيكم خطة التدريب و تجيبوا معاكم : الجواز & الترانسكربيت & صور بقياس معين والصور بدون غطاء رأس .\n- الفحص الطبي كان مطلوب العام الماضي لكن هذي السنة ما كان مطلوب وعلى العموم لو كان مطلوب راح يعطيكم اوراق الفحص الطبي عشان تسونه في الجامعة.\n- قبل اسبوعين من موعد الرحلة راح يسلمكم الـ certificate of eligibility ماراح تقدر تدخل اليابان بدونها .\n- قبل أسبوع من التدريب راح يجتمع معاكم ويعطيكم اوراق عشان الفيزا وقبل اسبوع من موعد الرحلة راح يسلمكم الفيزا .\n- يوم الرحلة في الصباح راح يجتمع معكم ويعطيكم بعض الأوراق تحتاجونها اذا وصلتوا اليابان مثل عنوان السكن ( عشان تعبي الفورم الي يطلبه منك مكتب الهجرة او شرطة المطار …) و رقم الموظف المسؤول عنكم في اليابان .\n- راح يحددون لكم رحلةمعينة تحجزونها وغالبا تكون من البحرين الى اليابان وعلى طيران الاتحاد (طريقة الحجز في القسم الجاي)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/174559/3", "user": "user8581", "ts": 1473112694000, "tid": 174559, "pn": 3}}', 1473112694000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1459174-ee399', 'stk-ahmed_sh', 'EE 399', 'info', '{"desc": "نوع التدريب ( Summer Training )\nاسم الشركة أو جهة التدريب : ارامكو\n\nالسنة : 2015\nالتخصص + الجامعة: هندسة كهربائية + KFUPM\nمكان التدريب + القسم : ابقيق + Southern Area Oil Projects Division (SAOPD)\nالمكافأة : 2000 ريال\nطريقة التقديم : موقعهم بالانترنت.\n\nإضافات ( مثلا : رأيك في الشركة , الإستفادة,… ) : معظم الشغل كان Project Managment (PMT) والاستفادة الكبيرة بالتخصص كانت من جهة الكونتراكتور.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/49", "user": "AHMED_SH", "ts": 1475237097000, "tid": 170460, "pn": 49}}', 1475237097000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1260873-ee399', 'stk-user82', 'EE 399', 'info', '{"desc": "حياك الله 🙂\n\nصندوق البريد صار قديم 🤠 محد يستخدم رسائل الحمام الزاجل الحين … فاقترح انك تحذف هالسطر\n\nمعلومات الدراسة في المرحلة الثانوية … ممكن ما تكون هالمعلومة مهمة للشركات ، وبالتالي تقدر تستغني عنها\n\nايش كانت مسؤولياتك ومهامك خلال فترة التدريب الصيفي ؟\n\nفي Skills بما إنها كلها مهارات تقنية … ممكن تكتبها Technical Skills :\n\nMicrosoft Office\nSimulation Software : Matlab ( Simulink ) & Orcad Pspice\nProgramming Languages : C++/C\nGraphics : Photoshop & Cinema4D (3D-designing)\nOperating Systems : Windows XP ,7 & 8\n\nهل فيه غيرها … إذا فيه غيرها مثل لغة برمجية أو برنامج ما هو بمذكور هنا … اذكره\n\nالجزء الخاص بـ STRENGHTS … يمكن يحتاج إلى إعادة صياغة ، بحيث يبرز بعض الجوانب عنك … مثل التخطيط ، العمل الجماعي ، … إلخ\n\nهل شاركت في أندية الجامعة … مثل نادي الهندسة الكهربائية ، وهل أنت مشترك في جمعيات أو عضويات عالمية معروفة مثل IEEE … إذا نعم … اذكرها\n\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/149066/16", "user": "user82", "ts": 1378562227000, "tid": 149066, "pn": 16}}', 1378562227000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1510801-ee399', 'stk-chemical_engineering', 'EE 399', 'info', '{"desc": "انت شكلك جامعة رابغ .\n\nعموما بالتوفيق موضوع السكن كان امر محزن ياشباب لكن لاتشيلوا هم سرعان مافرحت اكثر لان الشقق سعرها حوالي 1100 ريال وتشمل الكهرب والموية والانترنت يعني وفرت 400 ريال وتقعد لحالك فيها ودفع اخر الشهر احسن من سكن ارامكو المزدوج لانه غرفة صغيرة فيها شخصين بعد هم يختاروه لك يعني مو مريح .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181273/111", "user": "Chemical_Engineering", "ts": 1560203164000, "tid": 181273, "pn": 111}}', 1560203164000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1511626-ee399', 'stk-sal3m', 'EE 399', 'info', '{"desc": "سكن الظهران مليان بنات، السنه ذي قبلوا بنات بنسبه كبيره وابتلشوا بيهم\n\nالي تدريبه ب الظهران يحمد ربه، كل شي عندك كافيهات مطاعم اسواق واذا طفشت البحرين نص سساعه وانت هناك.\nصح ان الريموت ايريا كل شي فري وماعندك صرفيات لكن بتكون طفشان اغلب الوقت واذا شحنت سيارتك راح تدق مشاوير بس عشان تجي للظهران او الدمام.\nبالنسبه للسكن، في سكن ب ايجار شهري ١١٥٠ ريال بالعزيزيه اتوقع شامل الكهربا و المويه مدري عن النت.\nطبعا هم نزلونا عند الراشد بحي العليا ومعروف الاسعار هناك صلخ لين تقول امين.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181273/219", "user": "Sal3m", "ts": 1561579461000, "tid": 181273, "pn": 219}}', 1561579461000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1352605-ee399', 'stk-saudi_kfupm', 'EE 399', 'info', '{"desc": "السلام عليكم\n\nأنا حاب أتدرب في الصيفي في شركة الكهرباء في الرياض ان شاء الله\nوأخذت الأوراق المطلوبة من الجامعة\n\nبس حاب أعرف من الشباب اللي تدربوا قبلي وين مكان الفرع الرئيسي لشركة الكهرب اللي أقدر أقدم له أوراقي\n\nوشكراً", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/159871/1", "user": "saudi_kfupm", "ts": 1397572866000, "tid": 159871, "pn": 1}}', 1397572866000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1352635-ee399', 'stk-user8053', 'EE 399', 'info', '{"desc": "أول شيء لازم تخلص أمورك الآن مع الشركة ,\n\nلا يلزم حضورك , تقدر تخلي الوالد أو أحد الإخوان يذهب إلى المقر الرئيسي للشركة على طريق الملك فهد قريب من مركز الجوازات ومعه الأوراق كلها حقات الجامعة وصورة من بطاقة أحوالك كاتب عليها التفويض ويذهب إلى شخص اسمه “فيصل الزير” أعتقد ويتفاهم معه .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/159871/2", "user": "user8053", "ts": 1397576803000, "tid": 159871, "pn": 2}}', 1397576803000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p789842-ee399', 'stk-user5901', 'EE 399', 'info', '{"desc": "اخي الكريم\nانت حكمت على عينه يمكن ما تتعدى 3 او 4 هذا اولا\nثانيا: اتوقع الي قابلتهم قابلتهم خلال التدريب الصيفي اي انهم ما اخذو اي ماده elective يعني ماعندهم الا بيسك بينما طلاب الجامعات الثانيه الي تقارنهم بطلاب البترول مايتدرب الا بعد انهاء جميع المقررات\n\nايضا بالنسبه للخطه الدراسيه :\nاذا كنت ترا ان abet مقياس حقيقي لجودة المخرجات فلماذا تم اعتماد خطه الهندسه الكهربائيه في جامعه الملك فهد(التي تعتبرها انت انها غير مجدية) مع انها تخرج مهندس كهربائي عام ؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/102368/32", "user": "user5901", "ts": 1297689683000, "tid": 102368, "pn": 32}}', 1297689683000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1489357-ee399', 'stk-mr.a1', 'EE 399', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nأخوكم طالب هندسة كهربائية ، وطالع تدريب في صيف ١٧٣. حاليا عندي عرض من شلمبرجير متبقي إني أسوي الفحص الطبي وحسب نتيجته راح يتم الرد بالموافقة من عدمها ، وعرض ثاني من شركة فلور العربية وصلني اليوم وكل اللي باقي إني أعطيهم موافقتي.\n\nحاليا محتار هل أوافق على عرض فلور أو أنتظر وأواصل الإجراءات مع شلمبرجير. ميولي لشلمبرجير بشكل أكبر لكني متخوف من الفحص -باعتبار ما عندي فكرة عن كيفيته- وهل ممكن يرفضون أحد لأسباب محددة أو لا.\n\nيا ليت اللي عنده فكرة عن الفحص الطبي وهل القبول مضمون بعده أو لا + هل التدريب في فلور ممتاز وممكن أعطيها أولوية على شلمبرجير ؟\n\nشكرا لكم…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/178974/1", "user": "Mr.A1", "ts": 1521470279000, "tid": 178974, "pn": 1}}', 1521470279000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1234088-ee399', 'stk-abdul3333', 'EE 399', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nزملائي الأعزاء,\n\nأنا طالب هندسة كهرباء, والمفروض أسوي تدريبي الصيفي هالصيف, بس الى الآن, لسا ما لقيت أية فرصة في أية شركة. مر أسبوع من الصيف تقريباً, والوقت قاعد يمشي بسرعة جداً. وزيادة على كذا, الجامعة ماهي قادرة توفر لنا (نعم, أنا وكثيرين غيري) فرص, إضافة لكوني “إبن مواطنة”.\nأحس اني خلاص مستسلم. كنت ناوي أحذف التدريب الصيفي وأنزل مواد, عشان أستفيد من الوقت بقدر الإمكان. بس التشيرمن قالي “لا, ان شاء الله نلاقي لك فرصة, لا تقلق”.\n\nأية أفكار أو اقتراحات؟ افيدونا…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/145972/1", "user": "abdul3333", "ts": 1370945665000, "tid": 145972, "pn": 1}}', 1370945665000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1392453-ee399', 'stk-ibra1991', 'EE 399', 'info', '{"desc": "أتمنى أني اقدر أفيدك بتجربتي انا ميكانيكا سينس يعني بس عندي صيفي\nخلصت تدريبي بشركة الكهرباء الصيف هذا133\nالجامعة تعطي الطالب إختيارين اما انه يجيب فرصة التدريب (وهذا أفضل للجامعة) او الجامعة توفر له ( في يوم المهنة او عن طريق موقع التدريب\nهذا الشي سي للطلاب لان الشركة تنزل فرصتين وفيه عدد كبير من الطلاب )\nطبعا قبل سنتين من التدريب انا كنت ابحث عن الفرص بنفسي لآني اعرف تعقيدات الجامعة والإجراءات الي يطلبونها\nوكنت اروح للشركات واسأل عن فرص التدريب الصيفي عندهم و وش الإجراءات المطلوبة لكن فيه لخبطة كبيرة عند الشركات\nلان فيه برنامج اسمه هدف تابع لمؤسسة الموارد البشرية لجميع الطلاب حتى الي بالمدارس او حتى الي مو موظفين\nالحكومة تلزم الشركات انهم يدربون المتقدمين عن طريق البرنامج هذا.\nبالنسبة لشركة الكهرب انت تختار المنطقة وتروح للمحطة الي بالمنطقة الي تبغاها وتقدم عليهم لكن احيانا يكون عندهم ضغط لان الجامعات الي بنفس المدينة ترسل طلابها لازم تراسلهم من بدري\nانا لما رحت للكهرب طبعا لازم تكون عندك وثيقتين نموذج بيانات تعبيه الشركة (اسم المشرف عليك ارقام تلفونات الخ) والثاني خطاب من الجامعة انك مرشح للتدريب حتى الشركة تقبلك\nالوثيقتين للأسف الجامعة ما تصدرهم إلا بفصل واحد قبل التدريب وانت تكون مشغول بالدراسة وصعب علي انك تقدم\nراح اكتب رد ثاني اجاوب عن باقي الاسئلة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/164299/2", "user": "ibra1991", "ts": 1408798916000, "tid": 164299, "pn": 2}}', 1408798916000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1491946-ee399', 'stk-user11063', 'EE 399', 'info', '{"desc": "المقابلة كانت مع مدير الاتش ار، مهندس كهربائي، موظف في القسم Procurement\nالاسئلة عن مشروع التخرج ، والتدريب الصيفي\nوالتكنكال كان ايش تعرف عن PLC واسئلة بسيطة في الControl Systems", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/179266/6", "user": "user11063", "ts": 1525774291000, "tid": 179266, "pn": 6}}', 1525774291000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1227671-ee399', 'stk-m7mud', 'EE 399', 'info', '{"desc": "رحت اليوم لأدارة التدريب وسألتهم عن حالي ووضعي\nلأنو قدمت في الموقع غلى جميع الشركات ومعدلي 2.8\nوسألته هل احد قبلني اولا\nوقلي مافي فرص للتدريب الصيفي تخصص كهرب وانت ما انقبلت\nفلتلوا طيب اي شركه مايهم\nقال معد في فرص ابدا \"دبر نفسك دورلك واسطه ولا واحد من اهلك \"ولا تعتمد على الجامعه\nعشان ما تتأخر ترم زياده\n\nذحين ايش اسوي\nانا قلت اكيد الجامعه راح تتدبر فرصه من هنا ولا من هنا لا كن لا امل للتدريب الصيفي\nوكل اللي قدمت عليهم في يوم المهنه محد رد ((ضحكوا علينا))\n\nذحين ايش وجه الجامعه اللي ماتقدر تدبر فرصه تدريب صيفي لطلابها\nوالشركات اللي ما يهمها التدريب (لازم الواسطه)\nيا عيال قلبي حار لاكن العون على اللله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/145084/1", "user": "m7mud", "ts": 1369482101000, "tid": 145084, "pn": 1}}', 1369482101000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p168620-ee399', 'stk-user15', 'EE 399', 'info', '{"desc": "طبعا المهندسين في دائرة PDD يهتمون بخطوط الضغط العالي و حمايتها\n\nطبيعة عملهم مثل طبيعة عمل ( سكيكو) ولكن داخل ارمكوا و مسماهم الحركي (سكيكوا رامكو)\n\nفيها عدة وحد منها وحدة المهندسين\n- اكتشاف المشاكل الكهربائية و حلها\n- عمل التصاميم الهندسية لتركيب أو أزالة أو تغير مكان أداة كهربائية في المحطات الفرعية\n- تصميم عمل ( المرحلات realy ) و عمل ترتيب بين عملها\n- دعم الدوائر الأخرى بما يتخص بالتصاميم الكهربائية عالية الفولتية و المتوسطة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training-in-aramco/56257/9", "user": "user15", "ts": 1179139716000, "tid": 56257, "pn": 9}}', 1179139716000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1324704-ee399', 'stk-user2352', 'EE 399', 'info', '{"desc": "السلام عليكم\n\nكما يعلم الجميع يعتبر التدريب الصيفي من متطلبات التخرج من الجامعة ومن أهم متطلبات تسجيله إنهاء مواد التخصص LEVEL3\nعلى الأقل اربع كورسات مع ENGL214،\nوقد كثرت الإستفسارات عن ذلك فحبيت أوضح الخطوات مختصرة في هذا الموضوع ،\nأولاً: خطوات تسجيل التدريب الصيفي :-\n\n1- تروح لمكتب ادارة التدريب وتأخذ ورقة التعريف والترشيح للتدريب والمكتوب عليها “to whom may it concern”\nومعها نموذج فرصة تدريب صيفي\n\n2- تبدأ عملية البحث عن فرصة تدريب في إحدى الشركات التي ترغبها أما بنفسك أو تنتظر ليوم المهنة ،إذا قبلوك يرسلون لك خطاب وتوديه لشؤون التدريب …وإذا لا سمح الله ماحصلت لك شركة , عمادة التدريب يوفرون لك فرصة في اي مكان والمميزات يمكن ماتكون نفس اللي ببالك . ولا تنسى اعداد سيرتك الذاتية CV التي بموجبها مع ورقة الترشيح راح تحصل فرصة تدريبية.\n\n3- في التسجيل المبكر للصيفي تضيف مادة التدريب الصيفي XXX399\n\n4- توقع أوراقك من الدكتور المنسق للتدريب في قسمك الأكاديمي COORDINATOR مثل الدكتور سميرالغضبان لقسم الهندسة الكهربائية والدكتور سيف الكعبي لقسم الهندسة الميكانيكية والدكتور سمير العامر لقسم هندسة النظم.\n\n5-بعد توقيع أوراقك توديها لإدارة التدريب من أجل اعتماد تسجيلك واصدار خطاب الموافقة واوراق التقييم\n6- بعد نهاية الفاينلات تروح ادارة التدريب وتأخذ أوراقك في ظرف مختوم توديه معك للشركة علشان تبدأ التدريب وترسل صورة بالفاكس لإدارة التدريب باسم المشرف عليك في الشركة\n7- مطلوب منك تسليم تقريرين مرحليين PROGRESS REPORTS الاول بعد الاسبوع الثالث والثاني بعد السادس\n\n8- بعد انتهاء فترة التدريب شهرين تبدأ تكتب FINAL REPORT وتسلمه للكوردينيتور وتستعد للبرزنتيشن والقريد في النهاية راح يتحول من IC إلى NP اجتياز\n\nلمعرفة آخر الفرص الوظيفية والتدريبية ،،\nارعص على الرابط\nhttp://cday.kfupm.edu.sa/opps_search.aspx\n\nنماذج مفيدة للـCV\nhttps://www.dropbox.com/s/jas5chtol345lai/CVs%20samples.rar", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training/156194/1", "user": "user2352", "ts": 1391126871000, "tid": 156194, "pn": 1}}', 1391126871000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p302716-ee399', 'stk-user4485', 'EE 399', 'info', '{"desc": "إبداع\n\nبسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته\n\nلا اعرف من اين ابدا , ولا كيف ابدا كلامي\nفكلماتك واحداث القصة واروايه تعجزني عن التعبير\n4 ساعات من بعد تسجيلي في هذا المنتدى\nاول موضوع اقراه في هذا المنتدى\nهو الامثل والاجمل والاكمل((ماخوذه من مصطفى الاغا)) صدى الملاعب -MBC\n12 صباحاً بتوقيت مكة المكرمة\nوالله بصراحه اخي العزيز او مره ادخل هذا المنتدى سجلت فيه وشفت عنوان الموضوع في توقيع احد الاعضاء تقريباً--واصل -- يذكرني بواحد من فريق الشياب بالجامعة-محمد واصل\nطبعاً الاسم واضح كما احب انا اظهر به\nانا من جدة\n\nعجبتني في احد الاجزاءالاولى قلت\nزي لمن تقول للحضرمي انت يمني - رغم الوحده بس لسه أكثرهم مو معترفين فيها خصوصا اللي بالمملكه\nادرس بجامعة حضرموت للعلوم والتكنولوجيا -بحضرموت-الجمهورية اليمنية\nرغم انو عائلتي 99% سعودياً ((الحضارم قصصهم ما تخلص))\n6 من عيال عمي خريجي البترول والمعادن\nالوالد خريج الدفعه الاولى هندسة كهربائية جامعة الملك عبدالعزيز\n\nانا من الناس اللي عندهم حس التطوير والابداع\nتقريباً تفكيرك وتفكيري واحد\nانا احب افهم الشي ما احفظه وبعدين انا احب في الهندسة الكميائية بعض الاشياء زي\nعمليات التكرير والعمليات بشكل عام\nواحب اطور نفسي حيث انو الوالد يعمل في مصافي البترول منذ اكثر من 25 في المملكة وخارجها\nرغم انو جامعتي مستواها التعليمي منخفض\nوالكوادر غير قويه ولكن انا لا انتظر ابحث في الانترنت التواصل مع اصدقاء الوالد في تخصصي\nالحمدلله الحين في كتب الكترونيه PDF\nطبعاً في اليمن بشكل عام الامكانيات ضعيفة\nرغم انو جامعتي تعتبر جامعة سعودية مساهمه لانو اللي قام على بنائها الحضارم في السعوديه\nبقشان والعمودي والباقين\nوانا بصراحه كنت نواي ادخل المنتدى بامانه عشان استفسر عن التدريب الصيفي\nاريد معرفة ما المؤسسات التي تقوم بفعلها لطلاب الجامعة بحيث احاول انخرط معاهم بطريقتي الخاصة بحكم اني من جامعة اخرى ولا احمل الجنسية السعودية\nبس انا عيال البلد\nوبصراحه انا اغلب وقتي وانا على النت بس بحوث في مجال تخصصي\nتعرفت على خرجين في مصر وتقابلت معاهم هذا الصيف\nحاولت اخذ منهم دروس في تعلم برامج قويه ومهمه للمهندس الكميائي\nواهمها HYSYs\nوان شاء خلال العام القادم سوف نستضيف هذا الطالب في الجامعه لاعطائنا دوره في هذا البرنامج\nما رايك في هذا البرنامج وهل تويد بدراسة البرامج التطبقية؟؟؟؟\n\nاخيرا انا ااؤيد افكارك حيث انها تشبه مافي مخيلتي\n\nوتحسسني انك تتكلم عني\n\nفانا الشايب حق الكلية وبعدين مصلع بس فلاوي زيك وممثل فضيع\nولعى وقلت طوولعلى طووول تعرف في حضرموت الناس قليل وجاين من الوادي ويعتبروني مخلوق غريب\n\nاو شي لو رجع بيك الزمن لايام الكيلية هل كنت سوف تفكر بالنشاط الحيوي داخل الجامعة\nمثلاً انا الحين\nرئيس جمعية المهندس الكيميائي بجامعتي\nبس مش على حساب الدراسه\n\nوبايش تنصحني\n\nاتمنى لك التوفيق\nنسيت اقولك الوالد برضو متغرب له 3 سنين في بلد عربي شمال غرب افريقا((اكيد عرفتها)) وانا عنده الحين تدريب صيفي وزياره\nوانا في اليمن واخوي في مصر والوالده واخواني الباقي في جدة\nبس نحن الحضارم على طول حاملين الجوازات والشنط على قولت الاغنيه الحضرميه\n((الحضرمي ياخوي حتى في بلاده ما استقر حامل جوزاه والحقيبه لسفر ام لسعوديه او الكويت ولا لقطر))\n\nواسف على الاطالة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/60566/251", "user": "user4485", "ts": 1219464087000, "tid": 60566, "pn": 251}}', 1219464087000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1333277-ee399', 'stk-kfupm28', 'EE 399', 'info', '{"desc": "الله يعطيكم العافية جميع , وسبب استفساري انه اثناء التدريب الصيفي لاحظت ان من يقوم باختبارات الجهد العالي خليط من المهندسيين والفنيين خريجي كليات التقنية فحبيت اتأكد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/157365/5", "user": "KFUPM28", "ts": 1393164848000, "tid": 157365, "pn": 5}}', 1393164848000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p820322-ee399', 'stk-al_aim', 'EE 399', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته… 🌹 🌹\n\nأتمنى الجميع أن يكون بصحة وسلامة…\nالموضوع يا جماعة الخير … 🌹\n\nأني ناوي أخذ السمر ترينق في شركة الكهرباء… وأريد منكم لا هنتو… إلي عنده خطة التطبيق\nمن الطلاب ممن سبق لهم التطبيق في شركة الكهرباء… يرسلها لي ضروري في أقرب و قت ممكن…\n\nدمتم بود ❤️ 🥰", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training-program/105303/1", "user": "Al_aim", "ts": 1300621667000, "tid": 105303, "pn": 1}}', 1300621667000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p842957-ee399', 'stk-user2690', 'EE 399', 'info', '{"desc": "التدريب الصيفي ( ارامكو ولا شركة الكهرباء)\n\nياشباب ولله الحمد انقبلت في التدريب في\n\n1) ارامكو\n2)شركة الكهرباء\n\nمانستغنى عن نصايحكم\n\nوالله محتار حيرة مابعدها حيرة\n\nايش المميزات والعيوب\n\nشاكر ومقدر لكم مقدماً", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/107438/1", "user": "user2690", "ts": 1305057824000, "tid": 107438, "pn": 1}}', 1305057824000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p843304-ee399', 'stk-hzx_300', 'EE 399', 'info', '{"desc": "انا تدربت بسكيكو في دائرة التوزيع, طبعا تخصصي هندسة كهربائيه, تدريب صيفي ما حد يهتم لك يعني لازم تتعب على روحك وبالنهايه هي شهرين ما راح تستفيد منها كثير غير تغير عن الجامعه يعني شوف لك شيء يريحك بالصيف وارتاح, وانا اشوف رح ارامكو اذا كان قريب لك يعطوك راتب اكثر من سكيكو احسن لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/107438/3", "user": "hzx_300", "ts": 1305126196000, "tid": 107438, "pn": 3}}', 1305126196000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p843312-ee399', 'stk-malcolm_x', 'EE 399', 'info', '{"desc": "الله يوفقك\nانا ما اقدر افيدك الا بالدعاء ( طالب سفمور)\nلكن الي اعرفو انو في الكو اب والتدريب الصيفي شركة الكهرياء احسن من ارامكو\nوان شاء الله الشباب يفيدوك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/107438/4", "user": "Malcolm_x", "ts": 1305126834000, "tid": 107438, "pn": 4}}', 1305126834000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1477098-ee399', 'stk-instrument', 'EE 399', 'info', '{"desc": "الزميل عيد\nشكرا على التوضيح بخصوص خطوط الانتاج\n\n((اما بالنسبة للادارة مدير قسم الكهرباء مهندس مصري والمهندسين الهنود والمصاريه محتكرين المناصب ))\n\nهذي علة اغلب شركات الاسمنت تفضيل الجنسية البكستانية والهندية ثم المصرية ووالله البعض مايدري وين الله موديه\nوالكلام هذا عن خبرة\n#\nتصدق في واحد مبرمج شغل فرن مواد جديد عكس اتجاه لمدة دقايق\nقفلو الموضوع بينهم لان مدير الصيانة باكستاني مدير الانتاج باكستاني مدير المصنع باكستاني ولي كان بيحوس الفرن ولد خالة مدير المصنع!\nوالله لو هو سعودي لأنهو مستقبلة!\n#\nتخيل مداوم مرة وكانت انا السعودي الوحيد الي يشتغل في غرفة الدي سي اس\nدخل علي باكستاني عمره مايزيد عن 20 واعطاني ورقة مكتوب انه يسمح للكائن الحي دخول غرفة التحكم اي وقت\nاختفى الادمي بعد شهرين\nسألت عنه طلع تدريب صيفي وهو طالع باكستاني في جامعة باكستانية وابوه ماسك قسم!\n\nولاحتكار موب مشكلة هالجنسيات, يوجد اعضاء مجلس ادارة ومدراء عوام يفضلون هالجنسيات والبعض يصرح في مجالسهم الخاصة!\n\nبخصوص الدورات لو اتكلم عنها ممكن محد يتوظف بلأسمنت\n\nبعد هالسرد احب انصح طلاب البترول انت بيئتك ومخرجاتك التعليمية اكبر من هالشركات الي كثير منها تفتقد لأخلاقيات التنافس النزيه\nاذا جاك عرض من اسمنتات شف قبل الراتب, من مدير ادارتك اذا سعودي ومدير المصنع سعودي توكل على الله والله يوفقك\nاقلها يحمون ظهرك من مهندسي ضباع دول العالم الثالث", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/176600/36", "user": "Instrument", "ts": 1500665246000, "tid": 176600, "pn": 36}}', 1500665246000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1372541-ee399', 'stk-madridi-4', 'EE 399', 'info', '{"desc": "السلام عليكم …\n\nشركة فلور للي ما يعرفها هي شركة أمريكية ماسكه مشروع صدارة ومقرها بالخبر … و عندها الان فرص تدريب صيفي لطلاب الهندسة و بالأخص Electrical Engineering & Instrumentation\n\nللمعلومية أنا الان متقدم للشركة وأعرف 3 طبقوا الصيف الماضي واستفادوا كثيرا .\n\nلمن يود أن يتقدم بالطلب مراسلة\n\nEsraa.Nusair@fluor.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training-at-fluor/161824/1", "user": "Madridi-4", "ts": 1401185614000, "tid": 161824, "pn": 1}}', 1401185614000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p275480-ee399', 'stk-user1493', 'EE 399', 'info', '{"desc": "اية والله هذا اللي انا لمسته يوم اخذت معهم تدريب صيفي الله لا يعيدها…وقررت أني ما ارجع لهم نهائيااااااا 🤴\n\nيا رجل عالم ما تبي تشتغل…ما غير سوالف وبس الموضف يقفل مكتبه ويروح يتقهوا-يشرب قهوة- عند المدير 😁…امحق مدير:D\n\nيعين اللي يبي يطور نفسه ينسى ان فيه شركة بالمملكة اسمها كهرب…بس انشاء الله اذا جن الشركات المنافسه…سوف تنقرض هذه الشركة…😉\n\nمع الاعتذار من اخونا همة لاني خايف انه ياخذ بخاطره مني ❤️\n\nدمتم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/63544/68", "user": "user1493", "ts": 1213786278000, "tid": 63544, "pn": 68}}', 1213786278000, 1794826857, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
